SELECT 'https://example.org/oulad/id/enrollment/' || code_module || '/' || code_presentation || '/' || id_student AS enrollment, 'https://example.org/oulad/id/assessment/' || id_assessment AS assessment, date_submitted AS submitted, deadline_day AS deadline, date_submitted-deadline_day AS "daysLate" FROM student_assessment JOIN assessments USING(id_assessment) WHERE NOT is_banked AND date_submitted>deadline_day;
